parameters.functionCode:
const aiResponse = $json.message?.content || $json.choices?.[0]?.message?.content || '';
const userMessage = $('preprocessMessage').first().$json.message;

// Detectar intenciones usando keywords
let intent = 'general';
let leadScore = 0;

const buyingKeywords = ['precio', 'costo', 'comprar', 'contratar', 'cotización', 'presupuesto'];
const infoKeywords = ['información', 'detalles', 'características', 'funciones'];
const demoKeywords = ['demo', 'prueba', 'reunión', 'presentación', 'agendar'];

if (buyingKeywords.some(keyword => userMessage.toLowerCase().includes(keyword))) {
  intent = 'buying';
  leadScore = 80;
} else if (demoKeywords.some(keyword => userMessage.toLowerCase().includes(keyword))) {
  intent = 'demo_request';
  leadScore = 70;
} else if (infoKeywords.some(keyword => userMessage.toLowerCase().includes(keyword))) {
  intent = 'information';
  leadScore = 40;
}

return {
  aiResponse,
  userMessage,
  intent,
  leadScore,
  userId: $('preprocessMessage').first().$json.userId,
  timestamp: new Date().toISOString()
};

